div.script:
function addParticipantRow() {
    var tbody = document.getElementById('tn_rows');
    var rows = tbody.querySelectorAll('.tn-row');
    var nr = rows.length + 1;
    var row = document.createElement('tr');
    row.className = 'tn-row';
    row.innerHTML =
        '<td class="tn-nr">' + nr + '</td>' +
        '<td><input type="text" name="tn_name_' + nr + '" class="form-control form-control-sm"/></td>' +
        '<td><input type="number" name="tn_age_' + nr + '" class="form-control form-control-sm" style="width:80px" min="0" max="120"/></td>' +
        '<td><select name="tn_gender_' + nr + '" class="form-select form-select-sm">' +
        '<option value="">—</option>' +
        '<option value="male">männlich</option>' +
        '<option value="female">weiblich</option>' +
        '<option value="diverse">divers</option>' +
        '</select></td>' +
        '<td><input type="text" name="tn_zip_' + nr + '" class="form-control form-control-sm" style="width:80px"/></td>' +
        '<td><input type="text" name="tn_city_' + nr + '" class="form-control form-control-sm"/></td>' +
        '<td><select name="tn_role_' + nr + '" class="form-select form-select-sm">' +
        '<option value="">—</option>' +
        '<option value="EA">EA</option>' +
        '<option value="HA">HA</option>' +
        '<option value="HO">HO</option>' +
        '<option value="PR">PR</option>' +
        '<option value="SO">SO</option>' +
        '</select></td>' +
        '<td class="text-center"><input type="checkbox" name="tn_juleica_' + nr + '" class="form-check-input"/></td>' +
        '<td><button type="button" class="btn btn-sm btn-outline-danger" onclick="removeParticipantRow(this)"><i class="fa fa-trash"></i></button></td>';
    tbody.appendChild(row);
}
function removeParticipantRow(btn) {
    var row = btn.closest('tr');
    row.remove();
    // Nummer UND Feldnamen neu vergeben – der Controller liest tn_name_1..n
    // fortlaufend und bricht bei der ersten Lücke ab.
    var rows = document.querySelectorAll('#tn_rows .tn-row');
    rows.forEach(function(r, i) {
        var nr = i + 1;
        r.querySelector('.tn-nr').textContent = nr;
        r.querySelectorAll('[name]').forEach(function(el) {
            el.name = el.name.replace(/_\d+$/, '_' + nr);
        });
    });
}

var RC_INCOME_CATEGORIES = ['tn_fees', 'municipality', 'association', 'bjr', 'income_other'];
var RC_CATEGORY_OPTIONS =
    '<option value="">—</option>' +
    '<option value="tn_fees">Einnahme: Teilnehmerbeiträge</option>' +
    '<option value="municipality">Einnahme: Zuschuss Gemeinde</option>' +
    '<option value="association">Einnahme: Zuschuss Verband</option>' +
    '<option value="bjr">Einnahme: Zuschuss BJR/BezJR</option>' +
    '<option value="income_other">Einnahme: Sonstige Zuschüsse</option>' +
    '<option value="accommodation">Ausgabe: Unterkunft, Verpflegung, Miete</option>' +
    '<option value="transport">Ausgabe: Fahrtkosten</option>' +
    '<option value="referees">Ausgabe: Honorare Referenten</option>' +
    '<option value="allowances">Ausgabe: Aufwandsentschädigungen</option>' +
    '<option value="materials">Ausgabe: Arbeits- und Hilfsmittel</option>' +
    '<option value="jl_fees">Ausgabe: Kursgebühren JL-Schulung</option>' +
    '<option value="cost_other">Ausgabe: Sonstige Ausgaben</option>';

function addReceiptRow() {
    var tbody = document.getElementById('rc_rows');
    var rows = tbody.querySelectorAll('.rc-row');
    var nr = rows.length + 1;
    var row = document.createElement('tr');
    row.className = 'rc-row';
    row.innerHTML =
        '<td class="rc-nr">' + nr + '</td>' +
        '<td><input type="date" name="rc_date_' + nr + '" class="form-control form-control-sm"/></td>' +
        '<td><input type="text" name="rc_no_' + nr + '" class="form-control form-control-sm" style="width:90px"/></td>' +
        '<td><input type="text" name="rc_partner_' + nr + '" class="form-control form-control-sm"/></td>' +
        '<td><input type="text" name="rc_desc_' + nr + '" class="form-control form-control-sm"/></td>' +
        '<td><select name="rc_direction_' + nr + '" class="form-select form-select-sm">' +
        '<option value="expense">Ausgabe</option>' +
        '<option value="income">Einnahme</option>' +
        '</select></td>' +
        '<td><select name="rc_category_' + nr + '" class="form-select form-select-sm" onchange="syncReceiptDirection(this)">' +
        RC_CATEGORY_OPTIONS +
        '</select></td>' +
        '<td><input type="number" name="rc_amount_' + nr + '" class="form-control form-control-sm" style="width:110px" min="0" step="0.01"/></td>' +
        '<td><button type="button" class="btn btn-sm btn-outline-danger" onclick="removeReceiptRow(this)"><i class="fa fa-trash"></i></button></td>';
    tbody.appendChild(row);
}
function removeReceiptRow(btn) {
    var row = btn.closest('tr');
    row.remove();
    // Nummer UND Feldnamen neu vergeben – der Controller liest rc_*_1..n
    // fortlaufend und bricht bei der ersten Lücke ab.
    var rows = document.querySelectorAll('#rc_rows .rc-row');
    rows.forEach(function(r, i) {
        var nr = i + 1;
        r.querySelector('.rc-nr').textContent = nr;
        r.querySelectorAll('[name]').forEach(function(el) {
            el.name = el.name.replace(/_\d+$/, '_' + nr);
        });
    });
}
// Position (Kategorie) bestimmt die Art – verhindert unzulässige Kombinationen.
function syncReceiptDirection(sel) {
    if (!sel.value) { return; }
    var row = sel.closest('tr');
    if (!row) { return; }
    var dir = row.querySelector('select[name^="rc_direction_"]');
    if (!dir) { return; }
    if (RC_INCOME_CATEGORIES.indexOf(sel.value) !== -1) {
        dir.value = 'income';
    } else {
        dir.value = 'expense';
    }
}
// Verlangt die gewählte Förderart überhaupt eine Belegliste?
// Quelle ist requires_receipt der Förderart (data-Attribut der
// Option) — § 4.4 Jugendleiterschulung braucht z. B. keine.
// Ohne Auswahl konservativ Pflicht, wie serverseitig auch.
function grantTypeRequiresReceipt() {
    var sel = document.getElementById('grant_type_id');
    if (!sel) { return true; }
    var opt = sel.options[sel.selectedIndex];
    if (!opt) { return true; }
    var flag = opt.getAttribute('data-requires-receipt');
    return flag === null ? true : flag === '1';
}
// Entweder-oder: digitale Belegliste ODER Datei-Upload im Dokumentenblock.
function toggleDigitalReceipts() {
    var box = document.getElementById('use_digital_receipts');
    if (!box) { return; }
    var on = box.checked;
    var needed = grantTypeRequiresReceipt();
    document.getElementById('rc_wrapper').classList.toggle('d-none', !on);
    document.getElementById('rc_add_btn').classList.toggle('d-none', !on);
    var grp = document.getElementById('receipt_file_group');
    if (grp) { grp.classList.toggle('d-none', on); }
    var inp = document.getElementById('receipt_file');
    if (inp) { inp.required = !on && needed; }
    var badge = document.getElementById('receipt_file_badge');
    if (badge) { badge.classList.toggle('d-none', !needed); }
    var hint = document.getElementById('receipt_optional_hint');
    if (hint) { hint.classList.toggle('d-none', needed || on); }
}

// Neugründungsformular nur bei Gruppenstarthilfe (Code 4_7) einblenden.
function toggleFoundationFile() {
    var sel = document.getElementById('grant_type_id');
    var grp = document.getElementById('foundation_file_group');
    if (!sel) { return; }
    if (!grp) { return; }
    var opt = sel.options[sel.selectedIndex];
    var code = opt ? opt.getAttribute('data-code') : '';
    var on = code === '4_7';
    grp.classList.toggle('d-none', !on);
    var inp = document.getElementById('foundation_file');
    if (inp) { inp.required = on; }
}
function kjrInitApplyForm() {
    toggleDigitalReceipts();
    toggleFoundationFile();
    var sel = document.getElementById('grant_type_id');
    if (sel) {
        sel.addEventListener('change', toggleFoundationFile);
        // Die Belegliste-Pflicht hängt ebenfalls an der Förderart.
        sel.addEventListener('change', toggleDigitalReceipts);
    }
}
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', kjrInitApplyForm);
} else {
    kjrInitApplyForm();
}
